# AKAH C2 364 V5 — one-file offline-safe launcher, raw base immutable
param(
 [int]$MaxMicroMinutes=40,
 [int]$MaxCMAssets=364,
 [int]$MaxGapWindows=80,
 [switch]$Offline
)
$ErrorActionPreference='Stop'
$Downloads=Join-Path $HOME 'Downloads'
$Repo='C:\SIRAJ\Repositories\spot-speculation-bot'
$Base=Join-Path $Downloads 'AKAH_C2_364_FAST_V4'
$Legacy=Join-Path $Downloads 'AKAH_C2_MARKET_VAULT_V2'
$Out=Join-Path $Downloads 'AKAH_C2_364_DEEP_EVIDENCE_V5'
$Upload=Join-Path $Downloads 'AKAH_C2_364_V5_UPLOAD_PACKETS'
if (-not (Test-Path (Join-Path $Base 'C2_364_PLAN.csv'))) { throw 'V4 baseline missing: C2_364_PLAN.csv. Refuse to use a different universe.' }
$Python=Join-Path $Repo '.venv\Scripts\python.exe'
if (-not (Test-Path $Python)) {
  $cmd=Get-Command python -ErrorAction SilentlyContinue
  if (-not $cmd) { throw 'Python 3.9+ not found. Use installed Python.' }
  $Python=$cmd.Source
}
$ToolDir=Join-Path $Out 'tools'
New-Item -Path $ToolDir -ItemType Directory -Force | Out-Null
$PyFile=Join-Path $ToolDir 'akah_c2_evidence_v5.py'
$payload=''
$compressed=[Convert]::FromBase64String($payload)
$memory=[System.IO.MemoryStream]::new([byte[]]$compressed)
$gzip=[System.IO.Compression.GZipStream]::new($memory,[System.IO.Compression.CompressionMode]::Decompress)
$file=[System.IO.File]::Open($PyFile,[System.IO.FileMode]::Create,[System.IO.FileAccess]::Write)
try { $gzip.CopyTo($file) } finally { $file.Dispose(); $gzip.Dispose(); $memory.Dispose() }
& $Python $PyFile --selftest
if ($LASTEXITCODE -ne 0) { throw 'Selftest failure' }
Write-Host 'C2_V5_PRIMARY=ORIGINAL_364_FROM_RD18_SOURCE_PLAN'
Write-Host 'REUSE_V4_RAW=YES - NO_FULL_REDOWLOAD'
Write-Host 'CUTOFF=2023-12-31_NO_2024_NO_LIVE'
$ArgsList=@($PyFile, '--base', $Base, '--repo', $Repo, '--old-vault', $Legacy, '--out', $Out, '--upload', $Upload, '--max-cm-assets', [string]$MaxCMAssets, '--max-gap-windows', [string]$MaxGapWindows, '--max-micro-minutes', [string]$MaxMicroMinutes)
if ($Offline) { $ArgsList += '--offline' }
& $Python @ArgsList
$Code=$LASTEXITCODE
Write-Host ('C2_V5_EXIT_CODE='+$Code)
Write-Host ('UPLOAD_FOLDER='+$Upload)
if ($Code -ne 0) { throw ('C2_V5_FAILED_EXIT_'+$Code) }
